import React,{useState,useEffect} from 'react';import {supabase} from '../lib/supabase';import toast from 'react-hot-toast';import {Shield,Users,CreditCard,Database,RefreshCw,Trash2,Eye,Lock,Unlock} from 'lucide-react';
const SUPER_SECRET=process.env.REACT_APP_SUPER_ADMIN_SECRET||'kk-super-secret-2024';
export default function SuperAdmin(){const [authenticated,setAuthenticated]=useState(false);const [secretInput,setSecretInput]=useState('');const [stats,setStats]=useState({stores:0,users:0,sales:0,revenue:0});const [stores,setStores]=useState([]);const [loading,setLoading]=useState(false);const [selectedStore,setSelectedStore]=useState(null);
useEffect(()=>{const auth=sessionStorage.getItem('super_admin_auth');if(auth===SUPER_SECRET){setAuthenticated(true);loadGlobalStats();loadStores();}},[]);
const handleAuth=e=>{e.preventDefault();if(secretInput===SUPER_SECRET){sessionStorage.setItem('super_admin_auth',SUPER_SECRET);setAuthenticated(true);loadGlobalStats();loadStores();}else{toast.error('Invalid secret key');}};
const loadGlobalStats=async()=>{setLoading(true);try{const [storesRes,usersRes,salesRes]=await Promise.all([supabase.from('stores').select('id',{count:'exact',head:true}),supabase.from('staff').select('id',{count:'exact',head:true}),supabase.from('sales').select('total_amount')]);const totalRevenue=salesRes.data?.reduce((s,i)=>s+(i.total_amount||0),0)||0;setStats({stores:storesRes.count||0,users:usersRes.count||0,sales:salesRes.data?.length||0,revenue:totalRevenue});}catch(err){toast.error('Failed to load stats');}finally{setLoading(false);}};
const loadStores=async()=>{const {data}=await supabase.from('stores').select('*,staff(count),company_settings(company_name)');setStores(data||[]);};
const viewStoreDetails=async(storeId)=>{const {data}=await supabase.from('stores').select('*,company_settings(*),staff(*),products(count),sales(count)').eq('id',storeId).single();setSelectedStore(data);};
const toggleLock=async(storeId,currentLock)=>{await supabase.from('stores').update({locked:!currentLock}).eq('id',storeId);toast.success(`Store ${currentLock?'unlocked':'locked'}`);loadStores();};
const deleteStore=async(storeId)=>{if(!window.confirm('PERMANENTLY DELETE this store and all its data?'))return;await supabase.from('stores').delete().eq('id',storeId);toast.success('Store deleted');loadStores();loadGlobalStats();};
if(!authenticated){return(<div className="min-h-screen flex items-center justify-center bg-gray-900"><form onSubmit={handleAuth} className="bg-gray-800 p-8 rounded-xl shadow-2xl w-96"><Shield className="w-12 h-12 text-green-500 mx-auto mb-6"/><h1 className="text-2xl font-bold text-white text-center mb-6">Super Admin</h1><input type="password" placeholder="Enter secret key" value={secretInput} onChange={e=>setSecretInput(e.target.value)} className="w-full p-3 bg-gray-700 text-white border border-gray-600 rounded mb-4" autoFocus/><button className="w-full bg-green-600 text-white p-3 rounded font-bold">Authenticate</button></form></div>);}
return(<div className="min-h-screen bg-gray-900 text-white p-6"><div className="max-w-7xl mx-auto"><div className="flex justify-between items-center mb-8"><h1 className="text-3xl font-bold"><Shield className="inline mr-3 text-green-500"/>Super Admin</h1><button onClick={()=>{sessionStorage.removeItem('super_admin_auth');setAuthenticated(false);}} className="px-4 py-2 bg-red-600 rounded">Logout</button></div><div className="grid grid-cols-4 gap-4 mb-8"><div className="bg-gray-800 p-5 rounded-xl"><p className="text-gray-400">Total Stores</p><p className="text-3xl font-bold">{stats.stores}</p></div><div className="bg-gray-800 p-5 rounded-xl"><p className="text-gray-400">Total Users</p><p className="text-3xl font-bold">{stats.users}</p></div><div className="bg-gray-800 p-5 rounded-xl"><p className="text-gray-400">Total Sales</p><p className="text-3xl font-bold">{stats.sales}</p></div><div className="bg-gray-800 p-5 rounded-xl"><p className="text-gray-400">Total Revenue</p><p className="text-3xl font-bold">K{stats.revenue.toFixed(2)}</p></div></div><div className="bg-gray-800 rounded-xl overflow-hidden"><div className="p-4 border-b border-gray-700 flex justify-between"><h2 className="text-xl font-semibold">All Stores</h2><button onClick={loadStores} className="p-2 hover:bg-gray-700 rounded"><RefreshCw size={16}/></button></div><table className="w-full text-sm"><thead className="bg-gray-700"><tr><th className="p-3 text-left">Store</th><th className="p-3 text-left">Created</th><th className="p-3 text-left">Staff</th><th className="p-3 text-left">Status</th><th className="p-3 text-center">Actions</th></tr></thead><tbody>{stores.map(s=>(<tr key={s.id} className="border-b border-gray-700"><td className="p-3">{s.name}</td><td className="p-3">{new Date(s.created_at).toLocaleDateString()}</td><td className="p-3">{s.staff?.count||0}</td><td className="p-3"><span className={`px-2 py-1 rounded-full text-xs ${s.locked?'bg-red-900 text-red-300':'bg-green-900 text-green-300'}`}>{s.locked?'Locked':'Active'}</span></td><td className="p-3"><div className="flex gap-2 justify-center"><button onClick={()=>viewStoreDetails(s.id)} className="p-1 text-blue-400"><Eye size={16}/></button><button onClick={()=>toggleLock(s.id,s.locked)} className="p-1 text-yellow-400">{s.locked?<Unlock size={16}/>:<Lock size={16}/>}</button><button onClick={()=>deleteStore(s.id)} className="p-1 text-red-400"><Trash2 size={16}/></button></div></td></tr>))}</tbody></table></div>{selectedStore&&(<div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4"><div className="bg-gray-800 rounded-xl w-full max-w-2xl max-h-[80vh] overflow-auto"><div className="p-4 border-b border-gray-700 flex justify-between"><h3 className="text-xl font-bold">{selectedStore.name}</h3><button onClick={()=>setSelectedStore(null)} className="text-gray-400">✕</button></div><div className="p-4 space-y-4"><div className="grid grid-cols-2 gap-4"><div><p className="text-gray-400">Company</p><p>{selectedStore.company_settings?.company_name||'-'}</p></div><div><p className="text-gray-400">Email</p><p>{selectedStore.company_settings?.email||'-'}</p></div><div><p className="text-gray-400">Phone</p><p>{selectedStore.company_settings?.phone||'-'}</p></div><div><p className="text-gray-400">Products</p><p>{selectedStore.products?.count||0}</p></div><div><p className="text-gray-400">Sales</p><p>{selectedStore.sales?.count||0}</p></div><div><p className="text-gray-400">Locked</p><p>{selectedStore.locked?'Yes':'No'}</p></div></div><div><p className="text-gray-400 mb-2">Staff</p><div className="bg-gray-900 rounded p-2 max-h-40 overflow-auto">{selectedStore.staff?.map(s=>(<div key={s.id} className="text-sm py-1 border-b border-gray-800">{s.full_name} ({s.role}) - {s.email}</div>))}</div></div></div></div></div>)}</div></div>);}
